[
  {
    "section": "state_ownership",
    "name": "restore_epoch",
    "entry_yaml": "  - state: restore_epoch\n    status: active           # ADR-0006 is Proposed; entries become binding when it is Accepted\n    owner_system: save-load (SaveService)\n    adr: docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    interface: \"u32 in user://saves/<campaign_id>/slot_epoch.bin (8 bytes: u32 LE epoch + u32 LE hand-rolled CRC32 poly 0xEDB88320), durable (EPOCH_DURABLE) before request_restore; reaches the sim only as the request_restore / request_new_game argument and the read-only non-persisted non-hashed kernel.clock view (T, world_seed, restore_epoch); each WORLD generation header carries a read-only write-time recovery copy; advance = min(2^32-1, max(e_mem, e_slot)+1), carried (no advance) only for a Continue of the newest non-demoted QUIT generation\"\n    write_access: save-load-only (slot_epoch.bin written by the Save/Load worker)\n    referenced_by:\n      - docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    added: 2026-10-28\n    revised: \"\""
  },
  {
    "section": "state_ownership",
    "name": "save_ring_and_campaign_directory",
    "entry_yaml": "  - state: save_ring_and_campaign_directory\n    status: active           # ADR-0006 is Proposed\n    owner_system: save-load (SaveService)\n    adr: docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    interface: \"user://saves/<campaign_id>/ holds campaign.json (rebuildable hint), gen_0..gen_2.sav (ring of AUTOSAVE_GENERATIONS 3, ordered by header generation only), gen_<write_epoch>_<k>.tmp, .bak, .demoted, slot_epoch.bin, profile.sav + permanent profile.bak, campaign.lock, quarantine/g<generation>_<REASON>_<k>.sav; retired campaigns move to user://saves_retired/<campaign_id>/; Save/Load registers no state block and no hook\"\n    write_access: save-load-worker-only (one Thread per WriteJob; main thread polls)\n    referenced_by:\n      - docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    added: 2026-10-28\n    revised: \"\""
  },
  {
    "section": "interfaces",
    "name": "save_host_api",
    "entry_yaml": "  - contract: save_host_api\n    status: active           # ADR-0006 is Proposed\n    pattern: direct_call     # host-local reads and calls, never commands\n    producer: save-load\n    consumers:\n      - chart-table-menus\n      - hud-and-suit-layer\n      - debug-overlay\n    adr: docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    signal_signature: \"SaveService.new_game(world_seed: int) -> int; continue_campaign() -> int; save_and_quit() -> int (returns promptly); cancel_held_close() -> void; campaign_info() -> SaveInfo; list_saves() -> Array[SaveInfo]; retire_campaign(id) / delete_campaign(id) -> int; reads save_status (IDLE, WRITING, WRITTEN, FAILED), fail_escalated, restore_reason, restore_epoch (diagnostic); no save_now and no load(generation) outside dev builds\"\n    referenced_by:\n      - docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    added: 2026-10-28\n    revised: \"\""
  },
  {
    "section": "interfaces",
    "name": "save_container_file",
    "entry_yaml": "  - contract: save_container_file\n    status: active           # ADR-0006 is Proposed\n    pattern: shared_resource # on-disk file shared by writer, loader, tools and tests\n    producer: save-load\n    consumers:\n      - save-load-loader\n      - dump-save-dev-tool\n      - golden-fixture-tests\n    adr: docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    signal_signature: \"7-byte magic 53 59 4E 53 45 41 1A + layout id byte; u32 LE header_len; UTF-8 JSON header (closed field list, 64-bit values as exact-width lowercase hex, other numbers integral and < 2^53); block payloads = var_to_bytes(Dictionary) concatenated in block-table order; last 32 bytes = SHA-256 of all preceding bytes (format law)\"\n    referenced_by:\n      - docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    added: 2026-10-28\n    revised: \"\""
  },
  {
    "section": "interfaces",
    "name": "block_persistence_payload",
    "entry_yaml": "  - contract: block_persistence_payload\n    status: active           # ADR-0006 is Proposed\n    pattern: direct_call\n    producer: every-persisted-block-owner\n    consumers:\n      - save-load\n      - command-simulation-layer\n    adr: docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    signal_signature: \"snapshot(ctx) -> ctx.put(Dictionary): deep copy, plain data (null, bool, int64, finite float, String, Array, Dictionary with String or int keys, PackedByteArray/Int32Array/Int64Array; typed containers allowed; never Object, StringName, Vector2i or other vectors); restore(data: Dictionary, stored_version: int, ctx) validates into scratch then copies contents into the existing block object and reports failure only through ctx.fault(<OWNER>_RESTORE_*); a field that may exceed 2^53 is declared int64 in the owner schema\"\n    referenced_by:\n      - docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n      - docs/architecture/adr-0003-state-block-registry-and-owner-contract.md\n    added: 2026-10-28\n    revised: \"\""
  },
  {
    "section": "performance_budgets",
    "name": "save_main_thread_encode",
    "entry_yaml": "  - system: save_main_thread_encode_and_handoff\n    status: active           # ADR-0006 is Proposed\n    budget_ms: 4.0\n    adr: docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    notes: \"SAVE_ENCODE_BUDGET_MS 4 ms is a log-only threshold on var_to_bytes plus hand-off, additive to the kernel capture (SNAPSHOT_BUDGET_MS 16.7 ceiling); one frame per autosave above the 14.9 ms desktop target is accepted pending SAVE-WRK-1 f (OQ-14 ruling, mitigation rungs in ADR-0006 section 1.9); probed 2026-10-28 synthetic only\"\n    referenced_by:\n      - docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    added: 2026-10-28\n    revised: \"\""
  },
  {
    "section": "api_decisions",
    "name": "save_payload_encoding",
    "entry_yaml": "  - purpose: save_payload_encoding\n    status: active           # ADR-0006 is Proposed; SAVE-WRK-1 confirms on a release export\n    api: \"var_to_bytes(dictionary) per block, decoded with bytes_to_var only after trailer, block table and payload_sha256 pass, then a bounded type walk (MAX_DECODE_DEPTH 16, MAX_DECODE_NODES 250000) that rejects TYPE_OBJECT, StringName, vectors and non-finite floats; the worker re-decodes and walks what it wrote in VERIFYING\"\n    not: \"var_to_bytes_with_objects / bytes_to_var_with_objects; Resource, .tres, .res, ResourceLoader or load() for a save; JSON or base64 payloads; trusting the encoder to refuse objects (it encodes an Object as EncodedObjectAsID, probed 2026-10-28)\"\n    adr: docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    reason: \"Native, exact int64 (probed 2^53+1), one decode path and one fuzz target; stored bytes are not canonical, so state equality is state_hash and hash input is ADR-0005's canonical encoding\"\n    referenced_by:\n      - docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    added: 2026-10-28\n    revised: \"\""
  },
  {
    "section": "api_decisions",
    "name": "hex64_header_decode",
    "entry_yaml": "  - purpose: hex64_header_decode\n    status: active           # ADR-0006 is Proposed\n    api: \"String.hex_decode() then an exact-size check (8 or 16 bytes) then PackedByteArray.decode_s64 / decode_u64; encode with encode_s64 + hex_encode; header integers must be integral and strictly < 2^53\"\n    not: \"String.hex_to_int (saturates to INT64_MAX with an engine error on 16 f's, probed 2026-10-28); to_int(); any 64-bit or hashed value as a JSON number\"\n    adr: docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    reason: \"JSON.parse returns float for every number (2^53+1 parses to 2^53, probed); top-bit-set values read as negative GDScript ints by design\"\n    referenced_by:\n      - docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    added: 2026-10-28\n    revised: \"\""
  },
  {
    "section": "api_decisions",
    "name": "save_worker_thread",
    "entry_yaml": "  - purpose: save_worker_thread\n    status: active           # ADR-0006 is Proposed; SAVE-WRK-1 confirms\n    api: \"one Thread per WriteJob (RefCounted holding the Thread and a Mutex-guarded status record), Thread.start(callable.bind(PackedByteArray blocks, paths, ints)); main thread polls is_alive() and calls wait_to_finish() only on a dead thread; Save & Quit polls under SAVE_QUIT_TIMEOUT_MS on the monotonic source then request_shutdown; abandoned jobs are never killed\"\n    not: \"WorkerThreadPool; joining a live thread; call_deferred into Save/Load or the kernel; passing the worker a Node, block, read view or live-state container\"\n    adr: docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    reason: \"Thread.wait_to_finish and the pool wait take no timeout (training knowledge, UNVERIFIED); a stuck disk must cost a stale file, not a stuck frame; probed: a live sleeping thread did not delay process exit past 0.68 s\"\n    referenced_by:\n      - docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    added: 2026-10-28\n    revised: \"\""
  },
  {
    "section": "api_decisions",
    "name": "save_file_swap",
    "entry_yaml": "  - purpose: save_file_swap\n    status: active           # ADR-0006 is Proposed\n    api: \"generation swap: write gen_<write_epoch>_<k>.tmp, flush, close, re-open, re-hash, decode + walk; rename the position's old file to .bak; rename .tmp to the now-absent gen_k.sav; re-hash; delete .bak; every store_* and rename result checked; slot_epoch.bin and campaign.json use temp + rename-over (recoverable by rule)\"\n    not: \"relying on DirAccess.rename-over-existing for generations (it works on Windows when the target is unheld, probed, but a held target fails ERR_FAILED and crash atomicity is UNVERIFIED); overwriting in place; deleting a generation before its successor verified\"\n    adr: docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    reason: \"Every partial state is recoverable by T-6; sharing violations (antivirus, indexers) leave the target intact\"\n    referenced_by:\n      - docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    added: 2026-10-28\n    revised: \"\""
  },
  {
    "section": "api_decisions",
    "name": "campaign_lock",
    "entry_yaml": "  - purpose: campaign_lock\n    status: active           # ADR-0006 is Proposed; Linux/Deck behaviour UNVERIFIED (SAVE-WRK-1 g)\n    api: \"hold a FileAccess handle on campaign.lock for the campaign lifetime; a second process renames the file to campaign.lock.probe and back (only when the file exists; a missing file means not held); failure means held, so open READ_ONLY\"\n    not: \"an exclusive FileAccess.open (WRITE-open is not exclusive, probed 2026-10-28); OS.is_process_running liveness checks on a foreign pid\"\n    adr: docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    reason: \"Held files cannot be renamed or removed on Windows (probed); the handle dies with the process so no stale lock exists\"\n    referenced_by:\n      - docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    added: 2026-10-28\n    revised: \"\""
  },
  {
    "section": "forbidden_patterns",
    "name": "object_or_resource_in_save_payload",
    "entry_yaml": "  - pattern: object_or_resource_in_save_payload\n    status: active           # ADR-0006 is Proposed\n    description: \"No save, snapshot, profile or staged payload contains an Object, Resource, StringName, Vector2i or other vector/rect, Callable, Signal, RID, NodePath or non-finite float; the type walk enforces it at write (VERIFYING) and at load; var_to_bytes_with_objects, bytes_to_var_with_objects and Resource-based saves are never used.\"\n    why: \"var_to_bytes silently encodes an Object as EncodedObjectAsID (probed 2026-10-28), so the encoder is not a defence; a .tres can embed scripts.\"\n    adr: docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    added: 2026-10-28"
  },
  {
    "section": "forbidden_patterns",
    "name": "join_live_save_thread_or_workerthreadpool",
    "entry_yaml": "  - pattern: join_live_save_thread_or_workerthreadpool\n    status: active           # ADR-0006 is Proposed\n    description: \"Nothing calls wait_to_finish on a Thread that is still alive, uses WorkerThreadPool for the save writer, or blocks the main thread on save I/O; Thread is legal only inside the Save/Load module, one per WriteJob.\"\n    why: \"The join takes no timeout; a hung write would hang the frame at DEAD or at quit (CR-1a, exactly one thread boundary).\"\n    adr: docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    added: 2026-10-28"
  },
  {
    "section": "forbidden_patterns",
    "name": "hex_to_int_on_64bit_field",
    "entry_yaml": "  - pattern: hex_to_int_on_64bit_field\n    status: active           # ADR-0006 is Proposed\n    description: \"No 64-bit header or hash field is parsed with String.hex_to_int, int() or to_int(), or read from a JSON number; decode with hex_decode plus decode_s64 / decode_u64 after an exact-size check.\"\n    why: \"hex_to_int saturates at INT64_MAX with an engine error and JSON numbers are floats that corrupt values from 2^53 up (both probed 2026-10-28).\"\n    adr: docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    added: 2026-10-28"
  },
  {
    "section": "forbidden_patterns",
    "name": "restore_epoch_in_hash_or_snapshot",
    "entry_yaml": "  - pattern: restore_epoch_in_hash_or_snapshot\n    status: active           # ADR-0006 is Proposed\n    description: \"restore_epoch is never inside a block snapshot payload, a state_hash or block hash input, or a rewritten generation file; request_restore is called only after EPOCH_DURABLE (or the logged SL_EPOCH_NOT_DURABLE failure path); a step-back, demotion, quarantine or lost manifest never lowers it.\"\n    why: \"Keeps every generation immutable after VERIFYING so REBASED baselines hold, and keeps quit and death from being a reroll oracle (R13/R14).\"\n    adr: docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md\n    added: 2026-10-28"
  },
  {
    "section": "referenced_by_update",
    "name": "control_plane",
    "entry_yaml": "control_plane: add docs/architecture/adr-0006-save-container-generations-versioning-and-restore-epoch.md to referenced_by (Save/Load is the producer of request_snapshot / request_restore(payload, restore_epoch, expected_state_hash) / request_new_game / request_shutdown; the payload is a Dictionary StringName block_id -> {schema_version, data} and expected_state_hash is nullable)"
  },
  {
    "section": "referenced_by_update",
    "name": "owner_callable_contract",
    "entry_yaml": "owner_callable_contract: add ADR-0006 to referenced_by (snapshot/restore/default_state/post_restore payload rules; failure only through ctx.fault)"
  },
  {
    "section": "referenced_by_update",
    "name": "block_as_resource_or_node",
    "entry_yaml": "block_as_resource_or_node: add ADR-0006 to referenced_by (two-phase restore copies contents into the existing block object; no Resource saves)"
  },
  {
    "section": "referenced_by_update",
    "name": "fault_domain_table",
    "entry_yaml": "fault_domain_table: add ADR-0006 to referenced_by (domain 1 save_load registered by Save/Load at BOOTING with the SL_PRECHECK_/SL_WRITE_/SL_LOAD_/SL_VERIFY_/SL_EPOCH_/SL_QUIT_/SL_NEW_GAME_/SL_BOOT_ closed sets; none faults the kernel)"
  },
  {
    "section": "referenced_by_update",
    "name": "kernel_autoload_or_global",
    "entry_yaml": "kernel_autoload_or_global: add ADR-0006 to referenced_by (SaveService and SaveHost are constructed and injected by the composition root; no autoload)"
  },
  {
    "section": "referenced_by_update",
    "name": "static_content_catalogs",
    "entry_yaml": "static_content_catalogs / content_loading: add ADR-0006 to referenced_by (Save/Load knobs as a ScalarTable and assets/data/saveload/block_versions.json load through the ADR-0007 pipeline; catalogue_version int goes in the header)"
  }
]
