  },
  {
    "file": "design/gdd/save-load-and-versioned-format.md (SL-1, F-10)",
    "old": "hex decoding is exact-width ... no general string-to-int parse",
    "new": "add the mechanism: String.hex_decode() + exact-size check + decode_s64 / decode_u64; String.hex_to_int is banned (saturates to INT64_MAX with an engine error, probed)"
  },
  {
    "file": "design/gdd/save-load-and-versioned-format.md (SL-10)",
    "old": "`campaign.lock`, created with an exclusive open and holding the process id",
    "new": "FileAccess.open(WRITE) is not exclusive (probed); the lock is a FileAccess handle held for the campaign lifetime, tested by a rename probe run only when the file exists (missing = not held); pid is diagnostic; Linux/Deck unverified"
  },
  {
    "file": "design/gdd/save-load-and-versioned-format.md (T-5, SL-1)",
    "old": "T-5 steps 1 to 23 (no catalogue check)",
    "new": "add SL_PRECHECK_CATALOGUE_NEWER after step 12 (tick_rate) and before step 13: header catalogue_version above the build's is INCOMPATIBLE, no quarantine; catalogue_hash never gates"
  },
  {
    "file": "design/gdd/save-load-and-versioned-format.md (SL-19, OQ-27)",
    "old": "the physical reason encoding stays OQ-27",
    "new": "quarantine reason is in the file name quarantine/g<generation>_<REASON>_<k>.sav; retire_campaign moves the directory to user://saves_retired/<campaign_id>/; OQ-27 closed"
  },
  {
    "file": "design/gdd/save-load-and-versioned-format.md (OQ-14 and F-5)",
    "old": "OQ-14 / SAVE_HITCH_BUDGET_MS open",
    "new": "annotate: atomic SAVING kept, one over-budget frame per autosave accepted pending SAVE-WRK-1 f; mitigation rungs (skip unchanged blocks via cached hashes; encode on the worker; split capture only with a kernel amendment)"
  },
  {
    "file": "design/gdd/save-load-and-versioned-format.md (SL-10, SL-13)",
    "old": "`Thread.wait_to_finish` ... a join at the DEAD boundary; Save & Quit wait",
    "new": "record the probed result: a live thread does not delay process exit (0.68 s with an 8 s sleeping worker; ~Thread WARNING and ObjectDB leak report); Save & Quit is bounded polling under SAVE_QUIT_TIMEOUT_MS, never a join"
  },
  {
    "file": "design/gdd/life-support-graph.md (LS-21) and tr-baseline TR-lsg-022",
    "old": "never uses `var_to_bytes` or a Resource for saves",
    "new": "never uses Resource for saves and never uses var_to_bytes bytes as hash input; the Graph embeds canonical_bytes() as a PackedByteArray field of its snapshot dictionary (needs the Graph owner's confirmation, ADR-0011)"
  },
  {
    "file": "design/gdd/command-simulation-layer.md (CR-8) and tr-baseline TR-cmd-018",
    "old": "excluded from the snapshot header and all hashes",
    "new": "excluded from the kernel snapshot payload and every hash; the container header carries a read-only write-time recovery copy covered only by the file trailer"
  },
  {
    "file": "design/gdd/player-controller-input.md PC-17; ship-section-and-layout-data-model.md LY-26 a; tr-baseline TR-cmd-016, TR-pc-020, TR-section-007",
    "old": "restore() is a whole-block replace / swaps whole tables from scratch",
    "new": "restore validates into scratch, then replaces the block's contents in place (copy into the existing block object, never replace the object); root rule ADR-0003 section 2"
  },
  {
    "file": "design/gdd/suit-and-equipment.md SE-34 / AC-SE-35 and tr-baseline TR-suit-009",
    "old": "plain-data `snapshot()` (no Vector2i, StringName keys, typed containers)",
    "new": "String or int keys only; StringName keys and values are banned from files by the type walk; typed containers are allowed (they survive the encoder)"
  },
  {
    "file": "owner GDDs describing restore() returning (ok, reason, detail) (ADR-0003 sync)",
    "old": "two-phase `restore` returning `(ok, reason, detail)`",
    "new": "failure is reported through ctx.fault(<OWNER>_RESTORE_*) with the owner's domain code; Save/Load maps the kernel load_failed trigger to the RESTORE_FAILED class"
  },
  {
    "file": "design/gdd/ship-section-and-layout-data-model.md TR-section-006; modular-ship-assembly.md TR-assembly-013; ship-body-and-interior-physics.md TR-shipbody-007",
    "old": "64-bit values as two 32-bit halves or strings, never as JSON numbers",
    "new": "halves or strings remain legal; native int64 is also accepted in the binary payload (exact); the convention is mandatory only where a value can reach JSON (header, dump-save)"
  },
  {
    "file": "design/gdd/sanity-and-hallucination-rules.md TR-sanity-020",
    "old": "JSON-parsed integer-valued floats are accepted and re-cast to int",
    "new": "binary payload ints are exact, so a float where an int is expected is a SHAPE failure; the re-cast clause applies only to dev JSON fixtures"
  },
  {
    "file": "docs/architecture/architecture.md (Spikes that gate ADRs, Save worker row; Data Flow 6 and 7)",
    "old": "Save worker (DirAccess.rename over an existing file on Windows ... snapshot hitch size)",
    "new": "add the 2026-10-28 probe results and the SAVE-WRK-1 a to h checklist; note Save & Quit polls rather than joins; the quit-during-write bounded join is bounded polling"
  }
]

