// usage: node apply.js target blocks.txt
// blocks: "@@REPLACE <line prefix>" | "@@RANGE <start prefix> ||| <end prefix>" | "@@AFTER <line prefix>" | "@@SUBST <old>" (single-line old; new text is the block body, inline) ... "@@END"
const fs = require('fs');
const [,, target, blocksFile] = process.argv;
let lines = fs.readFileSync(target, 'utf8').split('\n');
const spec = fs.readFileSync(blocksFile, 'utf8').split('\n');
let i = 0; const ops = [];
while (i < spec.length) {
  const l = spec[i];
  if (l.startsWith('@@')) {
    const m = l.match(/^@@(\w+) ?(.*)$/);
    const body = []; i++;
    while (i < spec.length && spec[i] !== '@@END') { body.push(spec[i]); i++; }
    i++;
    ops.push({ kind: m[1], arg: m[2], body });
  } else i++;
}
function findLine(prefix, from = 0) {
  const idx = [];
  for (let k = from; k < lines.length; k++) if (lines[k].startsWith(prefix)) idx.push(k);
  if (idx.length !== 1) throw new Error(`prefix "${prefix}" matched ${idx.length} lines`);
  return idx[0];
